---Refresh 刷新记录
---@param catId integer @ 角色id
---@param status integer @ 状态
---@param topicId string
function UIFeelingCommunicationRightNode:Refresh(catId, status, topicId)
    self._curCatId = checkString(catId)
    self._curStatus = checkNumber(status)
    self._curCatVo = PhoneUtils.GetCatDojoById(self._curCatId)
    if not self._curCatVo then
        return
    end

    --刷新当前话题和信息
    if self._curStatus == Constants.CHATSOURCE.NORMAL then
        local t = phoneComp:GetCatCurChatInfo(self._curCatId)
        if t then
            self._curTopicId = checkString(t.curTalkContentId)
            self._curMessageId = checkString(t.curMessageId)
        else
            self._curTopicId = nil
            self._curMessageId = nil 
        end
    elseif self._curStatus == Constants.CHATSOURCE.LOOKHISTORY then
        self._curTopicId = checkString(topicId)
    elseif self._curStatus == Constants.CHATSOURCE.AGAIN then
        self._curTopicId = checkString(self._curTopicId)
        self._curMessageId = PhoneUtils.GetTalkCountFirstId(self._curTopicId)
    elseif self._curStatus == Constants.CHATSOURCE.YAOYIYAO then
        self._curTopicId = checkString(topicId)
        --摇一摇有缓存
        local t = phoneComp:GetYaoyiyaoReplyIndex()
        if t then
            self._replyIndexs = checkTable(t.replyIndexs)
            self._curMessageId = checkNumber(t.curMessageId)
        end
        if self._curMessageId == 0 then
            self._curMessageId = PhoneUtils.GetChatFirstId(self._curTopicId)
        end
        self._isYaoyiyaoChat = true
    else
        return
    end

    self:FillSelf()
end

function UIFeelingCommunicationRightNode:FillSelf()
    self:OnCloseInput()

    CfUtils.SetUISwitchImage(self.BtnRecord.transform:Find("ImgRecord"), self._curStatus == Constants.CHATSOURCE.LOOKHISTORY and 2 or 1)
    CfUtils.SetUISwitchText(self.BtnRecord.transform:Find("Text"), self._curStatus == Constants.CHATSOURCE.LOOKHISTORY and 2 or 1)

    CfUtils.FillText(self.NameText, self._curCatVo.name)
    --self:RefreshPageElements()

    self._allChatInfos = self:GetCatChatInfo()
    if not self._allChatInfos then
        return
    end
    self:RefeshChatInfoListView()

    self:HandleChatting()
end

--启动聊天
function UIFeelingCommunicationRightNode:HandleChatting()
    if self._chatCo then 
        cs_coroutine.stop(self._chatCo)
        self._chatCo = nil
    end
    
    local nextVo = PhoneUtils.GetNextMessageVo(self._curMessageId, self._isYaoyiyaoChat)
    --如果有下一句
    if nextVo then
        self._chatCo = cs_coroutine.start(function()
            --先判断上一句的间隔
            local isNpc = PhoneUtils.IsNpcMessage(self._curMessageId, self._isYaoyiyaoChat)
            --如果是npc说的话
            if isNpc then
                coroutine.yield(WaitForSeconds(self._npcTalkTime))
            else
                coroutine.yield(WaitForSeconds(self._meTalkTime))
            end
            
            --如果下一句是npc的 等待输入中
            isNpc = PhoneUtils.IsNpcMessage(nextVo.id, self._isYaoyiyaoChat)
            --如果是npc说的话
            if isNpc then
                table.insert(self._allChatInfos, {
                    roleId = self._curCatId,
                    type = Constants.PhoneChatType.Other,
                    content = localize("正在输入中")
                })
                self:RefeshChatInfoListView()
                coroutine.yield(WaitForSeconds(self._inputingTime))
                table.remove(self._allChatInfos, #self._allChatInfos)
            end
            self:SendMessage(nextVo.id)
        end)
    end
    self:RefreshPageElements()
end

function UIFeelingCommunicationRightNode:OnGetChatInfoCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._allChatInfos[index + 1]
    local cell 
    if data.type == Constants.PhoneChatType.Me then
        cell = listView:NewListViewItem("itemcelYour") 
    elseif data.type == Constants.PhoneChatType.NPC or data.type == Constants.PhoneChatType.Other then
        cell = listView:NewListViewItem("itemcelMy") 
    else
        cell = listView:NewListViewItem("DividingLine") 
    end

    local scr = CfUtils.GetLuaScr(cell, UIFeelingCommunicationChatInfoNode)
    if scr then
        scr:Refresh(data)
        if data.type ~= Constants.PhoneChatType.End then
            scr:ResetAnimator()
        end

        if index == table.count(self._allChatInfos) - 1 and data.type ~= Constants.PhoneChatType.Other and data.type ~= Constants.PhoneChatType.End then
            scr:PlayAnimator2()
        elseif data.type == Constants.PhoneChatType.Other then
            scr:PlayAnimator1()
        end
    end

    return cell
end

--发送一个话题
function UIFeelingCommunicationRightNode:SendTalkContent()
    --加层保护
    if self._isYaoyiyaoChat then
        return
    end
    if not self._curSelectTopicId then
        return 
    end
    local messageId = PhoneUtils.GetTalkCountFirstId(self._curSelectTopicId)
    if checkNumber(messageId) ~= 0 then
        phoneComp:SendTalkContentId(self._curCatId, self._curSelectTopicId, messageId)
        self._curSelectTopicId = nil
        self:Refresh(self._curCatId, Constants.CHATSOURCE.NORMAL)
    end
    --self:HandleChatting()
    self:OnCloseInput()
end

--发送一个消息
function UIFeelingCommunicationRightNode:SendMessage(messageId)
    if checkNumber(self._curCatId) == 0 then
        return
    end
    if self._curStatus == Constants.CHATSOURCE.NORMAL then
        phoneComp:SendMessageId(self._curCatId, messageId, self._curSelectReplyData)
        if PhoneUtils.IsMessageHasSelections(self._curMessageId, self._isYaoyiyaoChat) then
            if self._curSelectReplyData then
                messageId = PhoneUtils.GetMessageIdByTargetId(self._curTopicId, checkString(self._curSelectReplyData.targetId))
            end
        end
        self:OnCloseInput()
    elseif self._curStatus == Constants.CHATSOURCE.AGAIN then
        --如果最新的消息有回复 取回复数据
        if PhoneUtils.IsMessageHasSelections(self._curMessageId, self._isYaoyiyaoChat) then
            if self._curSelectReplyData then
                if self._replyIndexs then
                    table.insert(self._replyIndexs, checkNumber(self._curSelectReplyData.index))
                    messageId = PhoneUtils.GetMessageIdByTargetId(self._curTopicId, checkString(self._curSelectReplyData.targetId))
                    self:OnCloseInput()
                end
            end
        end
    elseif self._curStatus == Constants.CHATSOURCE.YAOYIYAO then
        --如果最新的消息有回复 取回复数据
        if PhoneUtils.IsMessageHasSelections(self._curMessageId, self._isYaoyiyaoChat) then
            if self._curSelectReplyData then
                if self._replyIndexs then
                    table.insert(self._replyIndexs, checkNumber(self._curSelectReplyData.index))
                    messageId = PhoneUtils.GetChatIdByTargetId(self._curTopicId, checkString(self._curSelectReplyData.targetId))
                    self:OnCloseInput()
                end
            end
        end
    else
        --直接return 出去
        return
    end

    self._curSelectReplyData = nil
    if checkNumber(messageId) ~= 0 then
        self._curMessageId = messageId
        self._allChatInfos[#self._allChatInfos + 1] = PhoneUtils.GetChatInfoByMessageId(messageId, self._curCatId, self._isYaoyiyaoChat) 
        if PhoneUtils.IsMessageIsEnd(self._curMessageId) then
            table.insert(self._allChatInfos, {
                messageId = 0,
                type = Constants.PhoneChatType.End,
            })
        end
        self:RefeshChatInfoListView()
        self:HandleChatting()
    else
        self:OnBtnSelectTopic()
    end
end

--点击聊天框
function UIFeelingCommunicationRightNode:OnBtnSelectTopic()
    if self._isPlayAni then
        return
    end

    if self._isOpenInput then
        self:OnCloseInput()
        return
    end
    if self._curStatus == Constants.CHATSOURCE.LOOKHISTORY then
        return
    end

    local isBeginTopic = self:IsBeginTopic()
    --如果开始了话题
    if isBeginTopic then
        local vo = PhoneUtils.GetPhoneMessageVo(self._curMessageId)
        --如果当前消息有回复

        if PhoneUtils.IsMessageHasSelections(self._curMessageId, self._isYaoyiyaoChat) then
            self:RefeshMessageInfo()
            KTool.SetActive(self.MessageBg, true)
        end
    --话题状态选择消息
    else
        local t = PhoneUtils.GetUnlockTalkContentIds(self._curCatId, Constants.PhoneTalkContentType.Message)
        if table.count(t) > 0 then 
            self:RefeshTalkContentInfo()
            self._chatBgDis = 420
            self:PlayChatBgAni()
        end
    end
end

--发送按钮
function UIFeelingCommunicationRightNode:OnBtnSend()
    if self._isPlayAni then
        return
    end

    local isBeginTopic = self:IsBeginTopic()
    --如果开始了一个话题
    if isBeginTopic then
        self:SendMessage()
    --没有话题
    elseif checkNumber(self._curSelectTopicId) > 0 then
        self:SendTalkContent()
    else 
        self:OnBtnSelectTopic()
    end
end

