        end)
    end
end

--关闭输入框
function UIFeelingCommunicationRightNode:OnCloseInput()
    if self._isPlayAni then
        return
    end
    
    if self._isOpenInput then
        KTool.SetActive(self.TopicGroup, false)
        CfUtils.FillText(self.MessageText, "")
        self:PlayChatBgRefeshAni()
        self._curSelectReplyData = nil
        self._curSelectTopicId = nil
    end
end

--刷新信息
function UIFeelingCommunicationRightNode:RefeshMessageInfo()
    local options = PhoneUtils.GetMessageSelections(self._curMessageId, self._isYaoyiyaoChat)
    if not options then
        return
    end
    self._chatBgDis =  self.MessageGo.rect.height * table.count(options)
    self:PlayChatBgAni()

    --先把全部的置灰
    for i = 1, self.MessageGroup.childCount do
        local go = self.MessageGroup.transform:Find("go"..i)
        if go then
            KTool.SetActive(go, false)
        end
    end

    for i, v in pairs(options) do
        local go = self.MessageGroup.transform:Find("go"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.MessageGo, self.MessageGroup)
            go.name = "go"..i
        end
        local scr = CfUtils.GetLuaScr(go, UIFeelingCommunicationReplyNode)
        if scr then
            scr:Refresh(v, function()
                if self._curSelectReplyData and checkNumber(self._curSelectReplyData.index) == checkNumber(i) then
                    return
                end
                --先把上一次的置灰
                if self._curSelectReplyData then
                    local lastGo = self.MessageGroup.transform:Find("go"..self._curSelectReplyData.index)
                    if lastGo then
                        local scr = CfUtils.GetLuaScr(lastGo, UIFeelingCommunicationReplyNode)
                        if scr then
                            scr:RefreshUnSelect()
                        end
                    end
                end
                self._curSelectReplyData = v
                CfUtils.FillText(self.MessageText, v.desc)
                local scr = CfUtils.GetLuaScr(go, UIFeelingCommunicationReplyNode)
                if scr then
                    scr:RefreshSelect()
                end
                self:RefreshBtnRecordImage(INPUTSTATE.TYPE3)
            end, i)
        end
    end
    KTool.SetActive(self.MessageGroup, true)
end

--刷新list
function UIFeelingCommunicationRightNode:RefeshChatInfoListView()
    if not self._isInitChatView then
        self.LoopViewChat:InitListView(#self._allChatInfos, Bind(self, self.OnGetChatInfoCellByIndex))
        self._isInitChatView = true
    else
        GameUtils.ReloadData(self.LoopViewChat, 0)
        GameUtils.ReloadData(self.LoopViewChat, #self._allChatInfos)
    end
    self.LoopViewChat:MovePanelToItemIndex(#self._allChatInfos, 0)
end

--刷新话题
function UIFeelingCommunicationRightNode:RefeshTalkContentInfo()
    if not self._curCatId then
        return
    end
    self._allTalkContentId = PhoneUtils.GetUnlockTalkContentIds(self._curCatId, Constants.PhoneTalkContentType.Message)
    if table.count(self._allTalkContentId) <= 0 then 
        GameUtils.Toast(localize("没有解锁的话题"))
        return
    end

    KTool.SetActive(self.MessageBg, true)
    if not self._isInitTalkContentView then
        self.TopicLoopView:InitGridView(#self._allTalkContentId, Bind(self, self.OnGetTalkContentCellByIndex))
        self._isInitTalkContentView = true
    else
        GameUtils.ReloadData(self.TopicLoopView, #self._allTalkContentId)
    end
    KTool.SetActive(self.TopicGroup, true)
end

function UIFeelingCommunicationRightNode:OnGetTalkContentCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allTalkContentId[index + 1]
    local cell = listView:NewListViewItem("itemcel")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingCommunicationTopicNode)
    if scr then
        scr:Refresh(id, function()
            if checkNumber(self._curSelectTopicId) ~= checkNumber(id) then
                self:OnSelectTalkCount(id)                
            end
        end, index)
    end
    return cell
end

---OnSelectTalkCount 选择一个话题
---@param topicId string 话题id
function UIFeelingCommunicationRightNode:OnSelectTalkCount(topicId)
    local vo = PhoneUtils.GetPhoneTalkContentVo(topicId)
    if not vo then
        return
    end
    self:RefreshBtnRecordImage(INPUTSTATE.TYPE3)

    local go
    if self._curSelectTopicId then
        go = self.TopicLoopView:GetShownItemByItemIndex(checkNumber(table.keyof(self._allTalkContentId, self._curSelectTopicId)) - 1)
        if go then
            local scr = CfUtils.GetLuaScr(go, UIFeelingCommunicationTopicNode)
            if scr then
                scr:RefreshUnSelect()
            end
        end
    end

    local vo = PhoneUtils.GetPhoneMessageVo(PhoneUtils.GetTalkCountFirstId(topicId))
    if vo then
        CfUtils.FillText(self.MessageText, vo.text)
    end
    self._curSelectTopicId = checkString(topicId)
    
    go = self.TopicLoopView:GetShownItemByItemIndex(checkNumber(table.keyof(self._allTalkContentId, self._curSelectTopicId)) - 1)
    if go then
        local scr = CfUtils.GetLuaScr(go, UIFeelingCommunicationTopicNode)
        if scr then
            scr:RefreshSelect()
        end
    end
end

--获取当前角色目前的聊天内容
function UIFeelingCommunicationRightNode:GetCatChatInfo()
    local tCur = {}   --当前说过的
    if self._curStatus == Constants.CHATSOURCE.LOOKHISTORY then
        tCur = PhoneUtils.GetCatTalkCountChatInfo(self._curCatId, self._curTopicId)
    elseif self._curStatus == Constants.CHATSOURCE.NORMAL then
        tCur = PhoneUtils.GetCatAllChatInfo(self._curCatId, self._curMessageId)
    elseif self._curStatus == Constants.CHATSOURCE.AGAIN then
        tCur = PhoneUtils.GetChatInfoByRelay(self._curCatId, self._curTopicId, self._replyIndexs, self._curMessageId)
    elseif self._curStatus == Constants.CHATSOURCE.YAOYIYAO then
        tCur = PhoneUtils.GetOnlyChatInfoByRelay(self._curCatId, self._curTopicId, self._replyIndexs, self._curMessageId)
    end
    return tCur
end

--是否开始了一个话题
function UIFeelingCommunicationRightNode:IsBeginTopic()
    return (checkNumber(self._curTopicId) ~= 0)
end 

--发送完话题刷新数据
function UIFeelingCommunicationRightNode:OnRefeshChattingInfo(body)
    self:Refresh(self._curCatId, Constants.CHATSOURCE.NORMAL)
end

function UIFeelingCommunicationRightNode:PlayChatBgAni()
    local dis = self._chatBgDis + 20
    self._isPlayAni = true
    CfUtils.DoTween(0.35, function(updateValue)
        local y = Mathf.Lerp(self._chatBgAutoPos.y, self._chatBgAutoPos.y + dis, updateValue)
        self.SendItem.localPosition = Vector3(self._chatBgAutoPos.x, y, 0)
        y = Mathf.Lerp(self._bgSelectionSizeData.y, self._bgSelectionSizeData.y + dis, updateValue)
        self.BgSelection.sizeDelta = Vector2(self._bgSelectionSizeData.x, y, 0)
        y = Mathf.Lerp(self._messageRootPos.y, self._messageRootPos.y + dis, updateValue)
        self.MessageGroup.localPosition = Vector3(self._messageRootPos.x, y, 0)
    end, function()
        self._isOpenInput = true
        self:RefreshInputImage(INPUTSTATE.TYPE3)
        self._isPlayAni = false
    end)
    
    local _d = 0
    if self.Content.sizeDelta.y > self.Viewport.sizeDelta.y then
        _d = dis
    elseif dis + self.Content.sizeDelta.y > self.Viewport.sizeDelta.y then
        _d = dis + self.Content.sizeDelta.y - self.Viewport.sizeDelta.y
    end
    CfUtils.DoTween(0.35, function(updateValue)
        self.Viewport.localPosition = Vector3(self._chatInfoAutoPos.x, self._chatInfoAutoPos.y + _d * updateValue, 0)
    end)
end

--还原回来
function UIFeelingCommunicationRightNode:PlayChatBgRefeshAni()
    local dis = self._chatBgDis + 10
    self._isPlayAni = true

    KTool.SetActive(self.MessageGroup, false)
    CfUtils.DoTween(0.35, function(updateValue)
        local y = Mathf.Lerp(self._chatBgAutoPos.y + dis, self._chatBgAutoPos.y, updateValue)
        self.SendItem.localPosition = Vector3(self._chatBgAutoPos.x, y, 0)

        y = Mathf.Lerp(self._bgSelectionSizeData.y + dis, self._bgSelectionSizeData.y, updateValue)
        self.BgSelection.sizeDelta = Vector2(self._bgSelectionSizeData.x, y, 0)
        y = Mathf.Lerp(self._messageRootPos.y + dis, self._chatBgAutoPos.y + dis, updateValue)
        self.MessageGroup.localPosition = Vector3(self._messageRootPos.x, y, 0)
    end, function()
        KTool.SetActive(self.MessageBg, false)
        self._isOpenInput = false
        self:RefreshInputFrame()
        self._isPlayAni = false
    end)

    local _d = 0
    if self.Content.sizeDelta.y > self.Viewport.sizeDelta.y then
        _d = dis
    elseif dis + self.Content.sizeDelta.y > self.Viewport.sizeDelta.y then
        _d = dis + self.Content.sizeDelta.y - self.Viewport.sizeDelta.y
    end
    CfUtils.DoTween(0.35, function(updateValue)
        self.Viewport.localPosition = Vector3(self._chatInfoAutoPos.x, self._chatInfoAutoPos.y + _d * (1 - updateValue), 0)
    end)
end

--刷新界面元素
function UIFeelingCommunicationRightNode:RefreshPageElements()
    self:RefreshOnLineImage()
    self:RefreshInputFrame()
end

--刷新输入框
function UIFeelingCommunicationRightNode:RefreshInputFrame()
    local isBeginTopic = self:IsBeginTopic()
    local state = INPUTSTATE.TYPE1
    --当前时查看历史
    if self._curStatus == Constants.CHATSOURCE.LOOKHISTORY then
    
    --如果已经开始了一个话题
    elseif isBeginTopic then
        local isCanReply = PhoneUtils.IsMessageHasSelections(self._curMessageId, self._isYaoyiyaoChat)
        if isCanReply then
            state = INPUTSTATE.TYPE2
        end
    else
        local t = PhoneUtils.GetUnlockTalkContentIds(self._curCatId, Constants.PhoneTalkContentType.Message)
        if t and table.count(t) > 0 then
            state = INPUTSTATE.TYPE2
        end
    end 

    self:RefreshInputImage(state)
    self:RefreshBtnRecordImage(state)
end

function UIFeelingCommunicationRightNode:RefreshInputImage(type)
    if type == INPUTSTATE.TYPE1 then
        CfUtils.FillText(self.MessageText, "")
        --CfUtils.FillImage(self.ImgBg, "UIAtlas/Feeling/Communication/feeling_chat_bg_3.png")
    elseif type == INPUTSTATE.TYPE2 then
        --CfUtils.FillImage(self.ImgBg, "UIAtlas/Feeling/Communication/feeling_chat_bg.png")
        CfUtils.FillText(self.MessageText, localize("点击输入聊天内容……"))
    elseif type == INPUTSTATE.TYPE3 then
        CfUtils.FillText(self.MessageText, localize("点击输入聊天内容……"))
        --CfUtils.FillImage(self.ImgBg, "UIAtlas/Feeling/Communication/feeling_chat_bg_2.png")
    end
end

function UIFeelingCommunicationRightNode:RefreshBtnRecordImage(type)
    if type == INPUTSTATE.TYPE1 then
        CfUtils.SetUISwitchImage(self.BtnSend, 2)
    elseif type == INPUTSTATE.TYPE2 then
        CfUtils.SetUISwitchImage(self.BtnSend, 1)
    elseif type == INPUTSTATE.TYPE3 then
        CfUtils.SetUISwitchImage(self.BtnSend, 1)
    end
end

--刷新在线状态
function UIFeelingCommunicationRightNode:RefreshOnLineImage()
    if checkNumber(self._curTopicId) ~= 0 then
        CfUtils.SetUISwitchImage(self.ImgstatePoint, 1)
    else
        CfUtils.SetUISwitchImage(self.ImgstatePoint, 2)
    end
end

--刷新回忆按钮
function UIFeelingCommunicationRightNode:RefreshBtnRecord()
    if self._curStatus == Constants.CHATSOURCE.AGAIN or self._curStatus == Constants.CHATSOURCE.LOOKHISTORY then 
        CfUtils.SetUISwitchImage(self.BtnRecord.transform:Find("ImgRecord"), 2)
        CfUtils.SetUISwitchText(self.BtnRecord.transform:Find("Text"), 2)
    else
        CfUtils.SetUISwitchImage(self.BtnRecord.transform:Find("ImgRecord"), 1)
        CfUtils.SetUISwitchText(self.BtnRecord.transform:Find("Text"), 1)
    end
end

function UIFeelingCommunicationRightNode:OnDestroy()
    if not isNull(self) then
        if self._chatCo then 
            cs_coroutine.stop(self._chatCo)
            self._chatCo = nil
        end
        Events.RemoveListener(Constants.EventNames.RefeshChattingInfo, self.EventRefeshChattingInfo)
    end

    if self._curStatus == Constants.CHATSOURCE.YAOYIYAO then
        phoneComp:SetYaoyiyaoReplyIndex({
            curMessageId = self._curMessageId,
            replyIndexs = self._replyIndexs,                        --回复的下标数组
        })
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingCommunicationRightNode
